const express = require('express');
const cors = require('cors');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = 5732;

app.use(cors());
app.use(express.json());

// Serve static files from the dist directory (built React app)
app.use(express.static(path.join(__dirname, 'dist')));

// In-memory comments store with some seed data
let comments = [
  {
    id: 'c1',
    text: 'Welcome! This is a nested comment system with optimistic updates.',
    parentId: null,
  },
  {
    id: 'c2',
    text: 'Try adding a comment — it appears instantly before the server responds!',
    parentId: 'c1',
  },
  {
    id: 'c3',
    text: 'The server has a 1000ms delay, but the UI updates in under 100ms.',
    parentId: 'c1',
  },
  {
    id: 'c4',
    text: 'TanStack Query makes optimistic updates straightforward.',
    parentId: null,
  },
];

// GET /api/comments — returns all comments
app.get('/api/comments', (req, res) => {
  res.status(200).json(comments);
});

// POST /api/comments — adds a new comment with a 1000ms artificial delay
app.post('/api/comments', (req, res) => {
  const { text, parentId = null } = req.body;

  if (!text || typeof text !== 'string' || text.trim() === '') {
    return res.status(400).json({ error: 'text is required' });
  }

  // Artificial 1000ms delay to make the optimistic update observable
  setTimeout(() => {
    const newComment = {
      id: uuidv4(),
      text: text.trim(),
      parentId: parentId || null,
    };

    comments.push(newComment);
    res.status(201).json(newComment);
  }, 1000);
});

// Fallback: serve the React app for any non-API route
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      '/api': 'http://localhost:5732',
    },
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import App from './App';
import './index.css';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 0,
      refetchOnWindowFocus: false,
    },
  },
});

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </React.StrictMode>
);

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --surface: #1a1d27;
  --surface-2: #22263a;
  --border: #2e3347;
  --accent: #6c63ff;
  --accent-hover: #5a52e0;
  --text: #e2e8f0;
  --text-muted: #8892a4;
  --success: #34d399;
  --optimistic: #fbbf24;
  --radius: 10px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  padding: 2rem 1rem;
}

#root {
  max-width: 760px;
  margin: 0 auto;
}

/* ── Header ─────────────────────────────────────── */
.header {
  margin-bottom: 2.5rem;
  text-align: center;
}

.header h1 {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.02em;
}

.header p {
  margin-top: 0.5rem;
  color: var(--text-muted);
  font-size: 0.925rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 35%, transparent);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  border-radius: 99px;
  margin-top: 0.875rem;
}

/* ── Add Comment Form ────────────────────────────── */
.add-comment-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.375rem 1.5rem;
  margin-bottom: 2rem;
}

.add-comment-card h2 {
  font-size: 0.925rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 1rem;
}

.form-row {
  display: flex;
  gap: 0.75rem;
}

.form-row input {
  flex: 1;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 7px;
  color: var(--text);
  font-size: 0.95rem;
  padding: 0.6rem 0.875rem;
  outline: none;
  transition: border-color 0.15s;
}

.form-row input::placeholder {
  color: var(--text-muted);
}

.form-row input:focus {
  border-color: var(--accent);
}

.btn-submit {
  background: var(--accent);
  border: none;
  border-radius: 7px;
  color: #fff;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.6rem 1.25rem;
  transition: background 0.15s, opacity 0.15s;
  white-space: nowrap;
}

.btn-submit:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-submit:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* ── Status bar ──────────────────────────────────── */
.status-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  margin-top: 0.75rem;
  min-height: 1.25rem;
}

.status-bar.pending {
  color: var(--optimistic);
}

.status-bar.success {
  color: var(--success);
}

.status-bar.error {
  color: #f87171;
}

.spinner {
  width: 12px;
  height: 12px;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
  display: inline-block;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ── Comments Section ────────────────────────────── */
.comments-section h2 {
  font-size: 0.925rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 1rem;
}

.loading-state,
.error-state,
.empty-state {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.error-state {
  color: #f87171;
  border-color: color-mix(in srgb, #f87171 30%, transparent);
}

/* ── Comment Thread ──────────────────────────────── */
.comment-thread {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}

.comment-item {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color 0.3s;
}

.comment-item.optimistic {
  border-color: var(--optimistic);
  animation: pulse-border 1.2s ease-in-out infinite;
}

@keyframes pulse-border {
  0%, 100% { border-color: var(--optimistic); }
  50%       { border-color: color-mix(in srgb, var(--optimistic) 35%, transparent); }
}

.comment-body {
  padding: 0.875rem 1rem;
}

.comment-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.comment-id {
  font-size: 0.7rem;
  color: var(--text-muted);
  font-family: monospace;
}

.optimistic-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--optimistic);
  background: color-mix(in srgb, var(--optimistic) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--optimistic) 30%, transparent);
  border-radius: 99px;
  padding: 0.15rem 0.5rem;
}

.comment-text {
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--text);
}

.comment-item.optimistic .comment-text {
  color: color-mix(in srgb, var(--text) 80%, var(--optimistic));
}

/* nested replies */
.comment-replies {
  border-top: 1px solid var(--border);
  padding: 0.625rem 0.75rem 0.625rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  background: color-mix(in srgb, var(--surface-2) 60%, transparent);
}

.reply-item {
  display: flex;
  gap: 0.625rem;
}

.reply-line {
  width: 2px;
  border-radius: 2px;
  background: var(--border);
  flex-shrink: 0;
}

.reply-item.optimistic .reply-line {
  background: var(--optimistic);
}

.reply-content {
  flex: 1;
}

.reply-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.25rem;
}

.reply-id {
  font-size: 0.65rem;
  color: var(--text-muted);
  font-family: monospace;
}

.reply-text {
  font-size: 0.875rem;
  color: var(--text);
  line-height: 1.5;
}

.reply-item.optimistic .reply-text {
  color: color-mix(in srgb, var(--text) 80%, var(--optimistic));
}

import { useRef, useState } from 'react';
import {
  useQuery,
  useMutation,
  useQueryClient,
} from '@tanstack/react-query';

// ─── API helpers ──────────────────────────────────────────────────────────────

const QUERY_KEY = ['comments'];

async function fetchComments() {
  const res = await fetch('/api/comments');
  if (!res.ok) throw new Error('Failed to fetch comments');
  return res.json();
}

async function postComment({ text, parentId = null }) {
  const res = await fetch('/api/comments', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, parentId }),
  });
  if (!res.ok) throw new Error('Failed to add comment');
  return res.json();
}

// ─── Comment components ───────────────────────────────────────────────────────

function Reply({ reply }) {
  const isOptimistic = reply._optimistic === true;
  return (
    <div className={`reply-item${isOptimistic ? ' optimistic' : ''}`}>
      <div className="reply-line" />
      <div className="reply-content">
        <div className="reply-meta">
          <span className="reply-id">#{reply.id.slice(0, 8)}</span>
          {isOptimistic && (
            <span className="optimistic-tag">
              <span className="spinner" style={{ width: 8, height: 8, borderWidth: 1.5 }} />
              pending
            </span>
          )}
        </div>
        <p className="reply-text">{reply.text}</p>
      </div>
    </div>
  );
}

function Comment({ comment, replies }) {
  const isOptimistic = comment._optimistic === true;
  return (
    <div className={`comment-item${isOptimistic ? ' optimistic' : ''}`}>
      <div className="comment-body">
        <div className="comment-meta">
          <span className="comment-id">#{comment.id.slice(0, 8)}</span>
          {isOptimistic && (
            <span className="optimistic-tag">
              <span className="spinner" style={{ width: 8, height: 8, borderWidth: 1.5 }} />
              pending
            </span>
          )}
        </div>
        <p className="comment-text">{comment.text}</p>
      </div>
      {replies.length > 0 && (
        <div className="comment-replies">
          {replies.map((r) => (
            <Reply key={r.id} reply={r} />
          ))}
        </div>
      )}
    </div>
  );
}

// Build a tree: top-level comments with their replies
function CommentThread({ comments }) {
  const topLevel = comments.filter((c) => c.parentId === null);
  const byParent = comments.reduce((acc, c) => {
    if (c.parentId) {
      acc[c.parentId] = acc[c.parentId] || [];
      acc[c.parentId].push(c);
    }
    return acc;
  }, {});

  if (topLevel.length === 0) {
    return (
      <div className="empty-state">No comments yet. Be the first!</div>
    );
  }

  return (
    <div className="comment-thread">
      {topLevel.map((c) => (
        <Comment
          key={c.id}
          comment={c}
          replies={byParent[c.id] || []}
        />
      ))}
    </div>
  );
}

// ─── Main App ─────────────────────────────────────────────────────────────────

export default function App() {
  const queryClient = useQueryClient();
  const inputRef = useRef(null);
  const [mutationStatus, setMutationStatus] = useState(null); // 'pending' | 'success' | 'error'

  // ── Fetch comments ──────────────────────────────────────────────────────────
  const {
    data: comments = [],
    isLoading,
    isError,
    error,
  } = useQuery({
    queryKey: QUERY_KEY,
    queryFn: fetchComments,
  });

  // ── Add comment mutation with full optimistic update lifecycle ───────────────
  const mutation = useMutation({
    mutationFn: postComment,

    // 1. Optimistically insert the new comment BEFORE the request completes
    onMutate: async (newComment) => {
      setMutationStatus('pending');

      // Cancel any in-flight refetches so they don't overwrite our optimistic data
      await queryClient.cancelQueries({ queryKey: QUERY_KEY });

      // Snapshot the current cache for rollback on error
      const previousComments = queryClient.getQueryData(QUERY_KEY);

      // Build the optimistic comment with a temporary id
      const optimisticComment = {
        id: `optimistic-${Date.now()}`,
        text: newComment.text,
        parentId: newComment.parentId ?? null,
        _optimistic: true,
      };

      // Inject the optimistic comment at the top of the list
      queryClient.setQueryData(QUERY_KEY, (old = []) => [
        optimisticComment,
        ...old,
      ]);

      // Return context so onError can roll back
      return { previousComments };
    },

    // 2. Roll back the cache if the mutation fails
    onError: (_err, _newComment, context) => {
      setMutationStatus('error');
      if (context?.previousComments) {
        queryClient.setQueryData(QUERY_KEY, context.previousComments);
      }
    },

    // 3. Always re-sync with the server after success or failure
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: QUERY_KEY });
    },

    onSuccess: () => {
      setMutationStatus('success');
      setTimeout(() => setMutationStatus(null), 2500);
    },
  });

  // ── Form submit ─────────────────────────────────────────────────────────────
  const handleSubmit = (e) => {
    e.preventDefault();
    const text = inputRef.current?.value?.trim();
    if (!text) return;
    mutation.mutate({ text, parentId: null });
    inputRef.current.value = '';
  };

  // ── Status message ──────────────────────────────────────────────────────────
  const renderStatus = () => {
    if (mutationStatus === 'pending') {
      return (
        <div className="status-bar pending">
          <span className="spinner" />
          Comment shown optimistically — waiting for server (1 s delay)…
        </div>
      );
    }
    if (mutationStatus === 'success') {
      return (
        <div className="status-bar success">
          ✓ Server confirmed — comment persisted
        </div>
      );
    }
    if (mutationStatus === 'error') {
      return (
        <div className="status-bar error">
          ✗ Server error — optimistic update rolled back
        </div>
      );
    }
    return <div className="status-bar" />;
  };

  // ── Render ──────────────────────────────────────────────────────────────────
  return (
    <div>
      <header className="header">
        <h1>Nested Comments</h1>
        <p>Powered by TanStack Query optimistic updates</p>
        <span className="badge">⚡ Optimistic Updates Demo</span>
      </header>

      {/* Add comment form */}
      <div className="add-comment-card">
        <h2>Add a comment</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-row">
            <input
              ref={inputRef}
              id="commentText"
              name="commentText"
              type="text"
              placeholder="Write something…"
              autoComplete="off"
              disabled={mutation.isPending}
            />
            <button
              id="submitComment"
              type="submit"
              className="btn-submit"
              disabled={mutation.isPending}
            >
              Submit
            </button>
          </div>
          {renderStatus()}
        </form>
      </div>

      {/* Comments list */}
      <section className="comments-section">
        <h2>Comments ({comments.length})</h2>

        {isLoading && (
          <div className="loading-state">
            <span className="spinner" style={{ marginRight: '0.5rem' }} />
            Loading comments…
          </div>
        )}

        {isError && (
          <div className="error-state">
            Failed to load comments: {error.message}
          </div>
        )}

        {!isLoading && !isError && (
          <CommentThread comments={comments} />
        )}
      </section>
    </div>
  );
}

